from pathlib import Path
R=Path(__file__).resolve().parents[1]/"site"
R.mkdir(exist_ok=True)
R.joinpath("index.html").write_text("""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Planificación clase a clase de los aprendizajes escolares chilenos."><title>Trayectoria Escolar Chile</title><link rel="stylesheet" href="styles.css"></head><body><header><nav><a class="brand" href="#">🇨🇱 Trayectoria Escolar Chile</a><a href="../README.md">Documentación</a><a href="../BOOKS_AND_READINGS.md">Textos y lecturas</a></nav><div class="hero"><p class="eyebrow">1° básico → 4° medio</p><h1>Todo aprendizaje merece tiempo, claridad y profundidad.</h1><p>Busca una clase por nivel, asignatura, tema u objetivo. Cada secuencia incluye explicación, práctica, apoyo, profundización y evidencia.</p><div id="stats" class="stats"></div></div></header><main><section class="finder"><div><label for="q">Tema, OA o palabra clave</label><input id="q" placeholder="Ej.: fracciones, ecosistemas"></div><div><label for="level">Nivel</label><select id="level"><option value="">Todos</option></select></div><div><label for="subject">Asignatura</label><select id="subject"><option value="">Todas</option></select></div><div><label for="coverage">Cobertura</label><select id="coverage"><option value="">Todas</option></select></div></section><p id="result"></p><section id="cards" class="cards" aria-live="polite"></section></main><footer>Proyecto educativo independiente · Fuentes oficiales enlazadas · Contenido abierto</footer><script src="app.js"></script></body></html>""",encoding="utf-8")
R.joinpath("styles.css").write_text("""*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;color:#172033;background:#f5f7fb}header{color:#fff;background:linear-gradient(135deg,#102a43,#126e82 58%,#e94f37)}nav{max-width:1180px;margin:auto;padding:22px;display:flex;gap:24px}nav a{color:#fff;text-decoration:none}.brand{font-weight:800;margin-right:auto}.hero{max-width:1180px;margin:auto;padding:65px 22px 80px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-weight:700}.hero h1{font-size:clamp(2.4rem,6vw,5.2rem);line-height:1;max-width:920px;margin:.2em 0}.hero>p{max-width:760px;font-size:1.2rem;line-height:1.6}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{background:#ffffff20;border:1px solid #ffffff55;padding:12px 16px;border-radius:14px}.stat b{display:block;font-size:1.4rem}main{max-width:1180px;margin:-35px auto 60px;padding:0 22px}.finder{background:#fff;padding:22px;border-radius:18px;box-shadow:0 14px 40px #19324d20;display:grid;grid-template-columns:2fr repeat(3,1fr);gap:14px}label{display:block;font-size:.82rem;font-weight:750;margin-bottom:7px}input,select{width:100%;padding:12px;border:1px solid #c8d3df;border-radius:10px;background:#fff}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:16px}.card{background:#fff;padding:20px;border-radius:16px;border:1px solid #dfe7ef}.card h2{font-size:1.05rem;margin:.5rem 0}.card a{color:#075985;font-weight:750}.tag{font-size:.76rem;background:#e8f3f5;color:#0c5664;padding:5px 8px;border-radius:999px}.meta{color:#5c6875;font-size:.88rem}.phase{color:#9c351f;font-weight:700}footer{text-align:center;padding:30px;color:#5c6875}@media(max-width:760px){nav a:not(.brand){display:none}.finder{grid-template-columns:1fr}.hero{padding-top:35px}.hero h1{font-size:2.5rem}}""",encoding="utf-8")
R.joinpath("app.js").write_text("""const q=s=>document.querySelector(s),state={all:[]};const uniq=(a,k)=>[...new Set(a.map(x=>x[k]))].sort((a,b)=>a.localeCompare(b,'es'));function opts(id,v){q(id).innerHTML+=v.map(x=>'<option>'+x+'</option>').join('')}function render(){let text=q('#q').value.toLowerCase(),lev=q('#level').value,sub=q('#subject').value,cov=q('#coverage').value,a=state.all.filter(x=>(!text||(x.topic+' '+x.oa_code+' '+x.oa_text+' '+x.axis).toLowerCase().includes(text))&&(!lev||x.course===lev)&&(!sub||x.subject===sub)&&(!cov||x.coverage===cov));q('#result').textContent=a.length.toLocaleString('es-CL')+' clases encontradas';q('#cards').innerHTML=a.slice(0,120).map(x=>'<article class="card"><span class="tag">'+x.course+'</span><p class="meta">'+x.subject+' · '+x.oa_code+'</p><h2>'+x.topic+'</h2><p class="phase">'+x.class_code+' · '+x.phase+'</p><p>'+x.axis+'</p><a href="../'+x.path+'">Abrir planificación →</a></article>').join('')||'<p>No hay coincidencias.</p>'}fetch('catalog.json').then(r=>r.json()).then(d=>{state.all=d.classes;q('#stats').innerHTML=[['Clases',d.class_count],['OA',d.objective_count],['Niveles',d.course_count],['Lecturas',d.reading_link_count]].map(x=>'<div class="stat"><b>'+x[1].toLocaleString('es-CL')+'</b>'+x[0]+'</div>').join('');opts('#level',uniq(state.all,'course'));opts('#subject',uniq(state.all,'subject'));opts('#coverage',uniq(state.all,'coverage'));document.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',render));render()})""",encoding="utf-8")
print("site written")

